INSERT INTO dict_cache (word, entry_json) VALUES
  ('root', '{"word":"root","phonetic":"/ru:t/","translation":"n. 根, 根本, 根源, 基础, 底部；vt. 使扎根, 使固定, 根除, 肃清, 搜出, 用鼻拱","translations":[{"id":"translation#0","text":"根","pos":"n","source":"ecdict"},{"id":"translation#1","text":"根本","pos":"n","source":"ecdict"},{"id":"translation#2","text":"根源","pos":"n","source":"ecdict"},{"id":"translation#3","text":"基础","pos":"n","source":"ecdict"},{"id":"translation#4","text":"底部","pos":"n","source":"ecdict"},{"id":"translation#5","text":"使扎根","pos":"vt","source":"ecdict"},{"id":"translation#6","text":"使固定","pos":"vt","source":"ecdict"},{"id":"translation#7","text":"根除","pos":"vt","source":"ecdict"},{"id":"translation#8","text":"肃清","pos":"vt","source":"ecdict"},{"id":"translation#9","text":"搜出","pos":"vt","source":"ecdict"},{"id":"translation#10","text":"用鼻拱","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"(botany) the usually underground organ that lacks buds or leaves or nodes; absorbs water and mineral salts; usually it anchors the plant to the ground"},{"id":"noun#1","pos":"noun","definition":"(linguistics) the form of a word after all affixes are removed"},{"id":"noun#2","pos":"noun","definition":"a number that, when multiplied by itself some number of times, equals a given number"},{"id":"noun#3","pos":"noun","definition":"the part of a tooth that is embedded in the jaw and serves as support"}],"cachedAt":1788515809767,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('father', '{"word":"father","phonetic":"/''fɑ:ðә/","translation":"n. 父亲, 祖先, 长辈, 神父, 创始者；vt. 当...的父亲, 保护, 创作, 发明, 培养","translations":[{"id":"translation#0","text":"父亲","pos":"n","source":"ecdict"},{"id":"translation#1","text":"祖先","pos":"n","source":"ecdict"},{"id":"translation#2","text":"长辈","pos":"n","source":"ecdict"},{"id":"translation#3","text":"神父","pos":"n","source":"ecdict"},{"id":"translation#4","text":"创始者","pos":"n","source":"ecdict"},{"id":"translation#5","text":"当...的父亲","pos":"vt","source":"ecdict"},{"id":"translation#6","text":"保护","pos":"vt","source":"ecdict"},{"id":"translation#7","text":"创作","pos":"vt","source":"ecdict"},{"id":"translation#8","text":"发明","pos":"vt","source":"ecdict"},{"id":"translation#9","text":"培养","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a male parent (also used as a term of address to your father)"},{"id":"noun#1","pos":"noun","definition":"`Father'' is a term of address for priests in some churches (especially the Roman Catholic Church or the Orthodox Catholic Church); `Padre'' is frequently used in the military"},{"id":"noun#2","pos":"noun","definition":"a person who holds an important or distinguished position in some organization"},{"id":"noun#3","pos":"noun","definition":"God when considered as the first person in the Trinity"}],"cachedAt":1788517674038,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('apple', '{"word":"apple","phonetic":"/''æpl/","translation":"n. 苹果, 家伙","translations":[{"id":"translation#0","text":"苹果","pos":"n","source":"ecdict"},{"id":"translation#1","text":"家伙","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"fruit with red or yellow or green skin and sweet to tart crisp whitish flesh"},{"id":"noun#1","pos":"noun","definition":"native Eurasian tree widely cultivated in many varieties for its firm rounded edible fruits"}],"cachedAt":1788517874756,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('head', '{"word":"head","phonetic":"/hed/","translation":"n. 头, 头脑, 领袖, 脑袋, 最前的部分；vt. 为首, 朝向, 前进, 用头顶","translations":[{"id":"translation#0","text":"头","pos":"n","source":"ecdict"},{"id":"translation#1","text":"头脑","pos":"n","source":"ecdict"},{"id":"translation#2","text":"领袖","pos":"n","source":"ecdict"},{"id":"translation#3","text":"脑袋","pos":"n","source":"ecdict"},{"id":"translation#4","text":"最前的部分","pos":"n","source":"ecdict"},{"id":"translation#5","text":"为首","pos":"vt","source":"ecdict"},{"id":"translation#6","text":"朝向","pos":"vt","source":"ecdict"},{"id":"translation#7","text":"前进","pos":"vt","source":"ecdict"},{"id":"translation#8","text":"用头顶","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the upper part of the human body or the front part of the body in animals; contains the face and brains"},{"id":"noun#1","pos":"noun","definition":"a single domestic animal"},{"id":"noun#2","pos":"noun","definition":"a person who is in charge"},{"id":"noun#3","pos":"noun","definition":"the front of a military formation or procession"}],"cachedAt":1788517874756,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('grape', '{"word":"grape","phonetic":"/greip/","translation":"n. 葡萄, 葡萄树","translations":[{"id":"translation#0","text":"葡萄","pos":"n","source":"ecdict"},{"id":"translation#1","text":"葡萄树","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"any of various juicy fruit of the genus Vitis with green or purple skins; grow in clusters"},{"id":"noun#1","pos":"noun","definition":"any of numerous woody vines of genus Vitis bearing clusters of edible berries"}],"cachedAt":1788515887674,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('moon', '{"word":"moon","phonetic":"/mu:n/","translation":"n. 月亮, 月球, 月光；vi. 闲荡","translations":[{"id":"translation#0","text":"月亮","pos":"n","source":"ecdict"},{"id":"translation#1","text":"月球","pos":"n","source":"ecdict"},{"id":"translation#2","text":"月光","pos":"n","source":"ecdict"},{"id":"translation#3","text":"闲荡","pos":"vi","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the natural satellite of the Earth"},{"id":"noun#1","pos":"noun","definition":"any object resembling a moon"},{"id":"noun#2","pos":"noun","definition":"United States religious leader (born in Korea) who founded the Unification Church in 1954; was found guilty of conspiracy to evade taxes (born in 1920)"},{"id":"noun#3","pos":"noun","definition":"any natural satellite of a planet"}],"cachedAt":1788515887676,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('black', '{"word":"black","phonetic":"/blæk/","translation":"n. 黑色, 黑颜料；a. 黑色的","translations":[{"id":"translation#0","text":"黑色","pos":"n","source":"ecdict"},{"id":"translation#1","text":"黑颜料","pos":"n","source":"ecdict"},{"id":"translation#2","text":"黑色的","pos":"a","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the quality or state of the achromatic color of least lightness (bearing the least resemblance to white)"},{"id":"noun#1","pos":"noun","definition":"British chemist who identified carbon dioxide and who formulated the concepts of specific heat and latent heat (1728-1799)"},{"id":"noun#2","pos":"noun","definition":"popular child actress of the 1930''s (born in 1928)"},{"id":"noun#3","pos":"noun","definition":"a person with dark skin who comes from Africa (or whose ancestors came from Africa)"}],"cachedAt":1788517874757,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('bad', '{"word":"bad","phonetic":"/bæd/","translation":"a. 坏的；n. 坏","translations":[{"id":"translation#0","text":"坏的","pos":"a","source":"ecdict"},{"id":"translation#1","text":"坏","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"that which is below standard or expectations as of ethics or decency"},{"id":"adjective#0","pos":"adjective","definition":"having undesirable or negative qualities"},{"id":"other#0","pos":"other","definition":"s. very intense"},{"id":"other#1","pos":"other","definition":"s. feeling physical discomfort or pain (`tough'' is occasionally used colloquially for `bad'')"}],"cachedAt":1788517874757,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('fish', '{"word":"fish","phonetic":"/fiʃ/","translation":"n. 鱼, 鱼肉, 鱼类, 接合板；vt. 钓, 钓鱼, 查出, 用接合板连接","translations":[{"id":"translation#0","text":"鱼","pos":"n","source":"ecdict"},{"id":"translation#1","text":"鱼肉","pos":"n","source":"ecdict"},{"id":"translation#2","text":"鱼类","pos":"n","source":"ecdict"},{"id":"translation#3","text":"接合板","pos":"n","source":"ecdict"},{"id":"translation#4","text":"钓","pos":"vt","source":"ecdict"},{"id":"translation#5","text":"钓鱼","pos":"vt","source":"ecdict"},{"id":"translation#6","text":"查出","pos":"vt","source":"ecdict"},{"id":"translation#7","text":"用接合板连接","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"A cold-blooded vertebrate animal that lives in water, moving with the help of fins and breathing with gills."},{"id":"noun#1","pos":"noun","definition":"Any animal (or any vertebrate) that lives exclusively in water."},{"id":"noun#2","pos":"noun","definition":"The flesh of the fish used as food."},{"id":"noun#3","pos":"noun","definition":"A card game in which the object is to obtain cards in pairs or sets of four (depending on the variation), by asking the other players for cards of a particular rank."},{"id":"noun#4","pos":"noun","definition":"A woman."},{"id":"noun#5","pos":"noun","definition":"An easy victim for swindling."},{"id":"noun#6","pos":"noun","definition":"A bad poker player. Compare shark (a good poker player)."},{"id":"noun#7","pos":"noun","definition":"A makeshift overlapping longitudinal brace, originally shaped roughly like a fish, used to temporarily repair or extend a spar or mast of a ship."},{"id":"noun#8","pos":"noun","definition":"A purchase used to fish the anchor."},{"id":"noun#9","pos":"noun","definition":"A torpedo."},{"id":"noun#10","pos":"noun","definition":"A paraphyletic grouping of the following extant taxonomic groups:"},{"id":"noun#11","pos":"noun","definition":"The thirty-fourth Lenormand card."}],"cachedAt":1788515887673,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
