  ('man', '{"word":"man","phonetic":"/mæn/","translation":"n. 男人, 人类, 人；vt. 为...配备人手, 操纵, 使振奋","translations":[{"id":"translation#0","text":"男人","pos":"n","source":"ecdict"},{"id":"translation#1","text":"人类","pos":"n","source":"ecdict"},{"id":"translation#2","text":"人","pos":"n","source":"ecdict"},{"id":"translation#3","text":"为...配备人手","pos":"vt","source":"ecdict"},{"id":"translation#4","text":"操纵","pos":"vt","source":"ecdict"},{"id":"translation#5","text":"使振奋","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"An adult male human."},{"id":"noun#1","pos":"noun","definition":"(collective) All human males collectively: mankind."},{"id":"noun#2","pos":"noun","definition":"A human, a person of either gender, usually an adult. (See usage notes.)"},{"id":"noun#3","pos":"noun","definition":"(collective) All humans collectively: mankind, humankind, humanity. (Sometimes capitalized as Man.)"},{"id":"noun#4","pos":"noun","definition":"A member of the genus Homo, especially of the species Homo sapiens."},{"id":"noun#5","pos":"noun","definition":"An male person, usually an adult; a (generally adult male) sentient being, whether human, supernatural, elf, alien, etc."},{"id":"noun#6","pos":"noun","definition":"An adult male who has, to an eminent degree, qualities considered masculine, such as strength, integrity, and devotion to family; a mensch."},{"id":"noun#7","pos":"noun","definition":"Manliness; the quality or state of being manly."},{"id":"noun#8","pos":"noun","definition":"A husband."},{"id":"noun#9","pos":"noun","definition":"A lover; a boyfriend."},{"id":"noun#10","pos":"noun","definition":"A male enthusiast or devotee; a male who is very fond of or devoted to a specified kind of thing. (Used as the last element of a compound.)"},{"id":"noun#11","pos":"noun","definition":"A person, usually male, who has duties or skills associated with a specified thing. (Used as the last element of a compound.)"},{"id":"interjection#0","pos":"interjection","definition":"Used to place emphasis upon something or someone; sometimes, but not always, when actually addressing a man."}],"cachedAt":1788515887675,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
