  ('tiger', '{"word":"tiger","phonetic":"/''taigә/","translation":"n. 老虎, 虎, 凶暴的人","translations":[{"id":"translation#0","text":"老虎","pos":"n","source":"ecdict"},{"id":"translation#1","text":"虎","pos":"n","source":"ecdict"},{"id":"translation#2","text":"凶暴的人","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a fierce or audacious person"},{"id":"noun#1","pos":"noun","definition":"large feline of forests in most of Asia having a tawny coat with black stripes; endangered"}],"cachedAt":1788515887681,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('mother', '{"word":"mother","phonetic":"/''mʌðә/","translation":"n. 母亲, 修女院长；vt. 产生, 照看, 收养","translations":[{"id":"translation#0","text":"母亲","pos":"n","source":"ecdict"},{"id":"translation#1","text":"修女院长","pos":"n","source":"ecdict"},{"id":"translation#2","text":"产生","pos":"vt","source":"ecdict"},{"id":"translation#3","text":"照看","pos":"vt","source":"ecdict"},{"id":"translation#4","text":"收养","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a woman who has given birth to a child (also used as a term of address to your mother)"},{"id":"noun#1","pos":"noun","definition":"a stringy slimy substance consisting of yeast cells and bacteria; forms during fermentation and is added to cider or wine to produce vinegar"},{"id":"noun#2","pos":"noun","definition":"a term of address for an elderly woman"},{"id":"noun#3","pos":"noun","definition":"a term of address for a mother superior"}],"cachedAt":1788515887676,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('sister', '{"word":"sister","phonetic":"/''sistә/","translation":"n. 姐妹, 姐, 妹, 护士, 修女；vt. 姐妹般对待","translations":[{"id":"translation#0","text":"姐妹","pos":"n","source":"ecdict"},{"id":"translation#1","text":"姐","pos":"n","source":"ecdict"},{"id":"translation#2","text":"妹","pos":"n","source":"ecdict"},{"id":"translation#3","text":"护士","pos":"n","source":"ecdict"},{"id":"translation#4","text":"修女","pos":"n","source":"ecdict"},{"id":"translation#5","text":"姐妹般对待","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a female person who has the same parents as another person"},{"id":"noun#1","pos":"noun","definition":"(Roman Catholic Church) a title given to a nun (and used as a form of address)"},{"id":"noun#2","pos":"noun","definition":"a female person who is a fellow member of a sorority or labor union or other group"}],"cachedAt":1788515887680,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('grandpa', '{"word":"grandpa","phonetic":"/''^rænpɑ:, ''^rændpɑ:/","translation":"爷爷, 老太爷, 外公","translations":[{"id":"translation#0","text":"爷爷","source":"ecdict"},{"id":"translation#1","text":"老太爷","source":"ecdict"},{"id":"translation#2","text":"外公","source":"ecdict"}],"senses":[{"id":"other#0","pos":"other","definition":"n the father of your father or mother"}],"cachedAt":1788515887673,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('grandma', '{"word":"grandma","phonetic":"/''grændmɑ:/","translation":"n. 奶奶, 外婆","translations":[{"id":"translation#0","text":"奶奶","pos":"n","source":"ecdict"},{"id":"translation#1","text":"外婆","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the mother of your father or mother"}],"cachedAt":1788515887673,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}');
