  ('boy', '{"word":"boy","phonetic":"/bɒi/","translation":"n. 男孩","translations":[{"id":"translation#0","text":"男孩","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a friendly informal reference to a grown man"},{"id":"noun#1","pos":"noun","definition":"(ethnic slur) offensive and disparaging term for Black man"}],"cachedAt":1788515887661,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('woman', '{"word":"woman","phonetic":"/''wumәn/","translation":"n. 女人, 妇女, 女仆；a. 女用的, 女性的, 妇女的","translations":[{"id":"translation#0","text":"女人","pos":"n","source":"ecdict"},{"id":"translation#1","text":"妇女","pos":"n","source":"ecdict"},{"id":"translation#2","text":"女仆","pos":"n","source":"ecdict"},{"id":"translation#3","text":"女用的","pos":"a","source":"ecdict"},{"id":"translation#4","text":"女性的","pos":"a","source":"ecdict"},{"id":"translation#5","text":"妇女的","pos":"a","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"an adult female person (as opposed to a man)"},{"id":"noun#1","pos":"noun","definition":"a female person who plays a significant role (wife or mistress or girlfriend) in the life of a particular man"}],"cachedAt":1788515887682,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('eye', '{"word":"eye","phonetic":"/ai/","translation":"n. 眼睛, 视力, 看；vt. 看, 注视","translations":[{"id":"translation#0","text":"眼睛","pos":"n","source":"ecdict"},{"id":"translation#1","text":"视力","pos":"n","source":"ecdict"},{"id":"translation#2","text":"看","pos":"n","source":"ecdict"},{"id":"translation#3","text":"看","pos":"vt","source":"ecdict"},{"id":"translation#4","text":"注视","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the organ of sight"},{"id":"noun#1","pos":"noun","definition":"good discernment (either visually or as if visually)"},{"id":"noun#2","pos":"noun","definition":"attention to what is seen"},{"id":"noun#3","pos":"noun","definition":"a small hole or loop (as in a needle)"}],"cachedAt":1788515887672,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('ear', '{"word":"ear","phonetic":"/iә/","translation":"n. 耳朵, 倾听, 听觉, 穗；vi. 抽穗","translations":[{"id":"translation#0","text":"耳朵","pos":"n","source":"ecdict"},{"id":"translation#1","text":"倾听","pos":"n","source":"ecdict"},{"id":"translation#2","text":"听觉","pos":"n","source":"ecdict"},{"id":"translation#3","text":"穗","pos":"n","source":"ecdict"},{"id":"translation#4","text":"抽穗","pos":"vi","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the sense organ for hearing and equilibrium"},{"id":"noun#1","pos":"noun","definition":"good hearing"},{"id":"noun#2","pos":"noun","definition":"attention to what is said"},{"id":"noun#3","pos":"noun","definition":"fruiting spike of a cereal plant especially corn"}],"cachedAt":1788515887671,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('nose', '{"word":"nose","phonetic":"/nәuz/","translation":"n. 鼻子, 突出部分, 嗅觉；vt. 嗅到, 探出, 用鼻子触","translations":[{"id":"translation#0","text":"鼻子","pos":"n","source":"ecdict"},{"id":"translation#1","text":"突出部分","pos":"n","source":"ecdict"},{"id":"translation#2","text":"嗅觉","pos":"n","source":"ecdict"},{"id":"translation#3","text":"嗅到","pos":"vt","source":"ecdict"},{"id":"translation#4","text":"探出","pos":"vt","source":"ecdict"},{"id":"translation#5","text":"用鼻子触","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the organ of smell and entrance to the respiratory tract; the prominent part of the face of man or other mammals"},{"id":"noun#1","pos":"noun","definition":"a front that resembles a human nose (especially the front of an aircraft)"},{"id":"noun#2","pos":"noun","definition":"the front or forward projection of a tool or weapon"},{"id":"noun#3","pos":"noun","definition":"a small distance"}],"cachedAt":1788515887676,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('mouth', '{"word":"mouth","phonetic":"/mauθ/","translation":"n. 嘴, 口, 口腔, 口状物；vi. 装腔作势说话, 做鬼脸","translations":[{"id":"translation#0","text":"嘴","pos":"n","source":"ecdict"},{"id":"translation#1","text":"口","pos":"n","source":"ecdict"},{"id":"translation#2","text":"口腔","pos":"n","source":"ecdict"},{"id":"translation#3","text":"口状物","pos":"n","source":"ecdict"},{"id":"translation#4","text":"装腔作势说话","pos":"vi","source":"ecdict"},{"id":"translation#5","text":"做鬼脸","pos":"vi","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the opening through which food is taken in and vocalizations emerge"},{"id":"noun#1","pos":"noun","definition":"the externally visible part of the oral cavity on the face and the system of organs surrounding the opening"},{"id":"noun#2","pos":"noun","definition":"an opening that resembles a mouth (as of a cave or a gorge)"},{"id":"noun#3","pos":"noun","definition":"the point where a stream issues into a larger body of water"}],"cachedAt":1788517874759,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('tooth', '{"word":"tooth","phonetic":"/tu:θ/","translation":"n. 牙齿, 齿状物, 爱好；vt. 装以齿, 将...切成齿状","translations":[{"id":"translation#0","text":"牙齿","pos":"n","source":"ecdict"},{"id":"translation#1","text":"齿状物","pos":"n","source":"ecdict"},{"id":"translation#2","text":"爱好","pos":"n","source":"ecdict"},{"id":"translation#3","text":"装以齿","pos":"vt","source":"ecdict"},{"id":"translation#4","text":"将...切成齿状","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"hard bonelike structures in the jaws of vertebrates; used for biting and chewing or for attack and defense"},{"id":"noun#1","pos":"noun","definition":"something resembling the tooth of an animal"},{"id":"noun#2","pos":"noun","definition":"toothlike structure in invertebrates found in the mouth or alimentary canal or on a shell"},{"id":"noun#3","pos":"noun","definition":"a means of enforcement"}],"cachedAt":1788515887681,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('hand', '{"word":"hand","phonetic":"/hænd/","translation":"n. 手, 爪, 指针, 掌握, 协助, 人手, 手艺, 手迹, 支配, 插手；vt. 交给, 支持, 搀扶","translations":[{"id":"translation#0","text":"手","pos":"n","source":"ecdict"},{"id":"translation#1","text":"爪","pos":"n","source":"ecdict"},{"id":"translation#2","text":"指针","pos":"n","source":"ecdict"},{"id":"translation#3","text":"掌握","pos":"n","source":"ecdict"},{"id":"translation#4","text":"协助","pos":"n","source":"ecdict"},{"id":"translation#5","text":"人手","pos":"n","source":"ecdict"},{"id":"translation#6","text":"手艺","pos":"n","source":"ecdict"},{"id":"translation#7","text":"手迹","pos":"n","source":"ecdict"},{"id":"translation#8","text":"支配","pos":"n","source":"ecdict"},{"id":"translation#9","text":"插手","pos":"n","source":"ecdict"},{"id":"translation#10","text":"交给","pos":"vt","source":"ecdict"},{"id":"translation#11","text":"支持","pos":"vt","source":"ecdict"},{"id":"translation#12","text":"搀扶","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"the (prehensile) extremity of the superior limb"},{"id":"noun#1","pos":"noun","definition":"ability"},{"id":"noun#2","pos":"noun","definition":"a position given by its location to the side of an object"},{"id":"noun#3","pos":"noun","definition":"the cards held in a card game by a given player at any given time"}],"cachedAt":1788515887674,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('arm', '{"word":"arm","phonetic":"/ɑ:m/","translation":"n. 手臂, 袖子, 狭长港湾, 武器；vt. 武装, 装备","translations":[{"id":"translation#0","text":"手臂","pos":"n","source":"ecdict"},{"id":"translation#1","text":"袖子","pos":"n","source":"ecdict"},{"id":"translation#2","text":"狭长港湾","pos":"n","source":"ecdict"},{"id":"translation#3","text":"武器","pos":"n","source":"ecdict"},{"id":"translation#4","text":"武装","pos":"vt","source":"ecdict"},{"id":"translation#5","text":"装备","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a human limb; technically the part of the superior limb between the shoulder and the elbow but commonly used to refer to the whole superior limb"},{"id":"noun#1","pos":"noun","definition":"any projection that is thought to resemble a human arm"},{"id":"noun#2","pos":"noun","definition":"the part of an armchair or sofa that supports the elbow and forearm of a seated person"},{"id":"verb#0","pos":"verb","definition":"prepare oneself for a military confrontation"}],"cachedAt":1788515887660,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('leg', '{"word":"leg","phonetic":"/leg/","translation":"n. 腿, 假腿, 路程；vi. 走, 跑","translations":[{"id":"translation#0","text":"腿","pos":"n","source":"ecdict"},{"id":"translation#1","text":"假腿","pos":"n","source":"ecdict"},{"id":"translation#2","text":"路程","pos":"n","source":"ecdict"},{"id":"translation#3","text":"走","pos":"vi","source":"ecdict"},{"id":"translation#4","text":"跑","pos":"vi","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a human limb; commonly used to refer to a whole limb but technically only the part of the limb between the knee and ankle"},{"id":"noun#1","pos":"noun","definition":"a structure in animals that is similar to a human leg and used for locomotion"},{"id":"noun#2","pos":"noun","definition":"one of the supports for a piece of furniture"},{"id":"noun#3","pos":"noun","definition":"the limb of an animal used for food"}],"cachedAt":1788515887675,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('banana', '{"word":"banana","phonetic":"/bә''nɑ:nә/","translation":"n. 香蕉","translations":[{"id":"translation#0","text":"香蕉","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"any of several tropical and subtropical treelike herbs of the genus Musa having a terminal crown of large entire leaves and usually bearing hanging clusters of elongated fruits"},{"id":"noun#1","pos":"noun","definition":"elongated crescent-shaped yellow fruit with soft sweet flesh"}],"cachedAt":1788517874759,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('orange', '{"word":"orange","phonetic":"/''ɒ:rindʒ/","translation":"n. 柑橘, 桔子, 橘色；a. 橘色的","translations":[{"id":"translation#0","text":"柑橘","pos":"n","source":"ecdict"},{"id":"translation#1","text":"桔子","pos":"n","source":"ecdict"},{"id":"translation#2","text":"橘色","pos":"n","source":"ecdict"},{"id":"translation#3","text":"橘色的","pos":"a","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"round yellow to orange fruit of any of several citrus trees"},{"id":"noun#1","pos":"noun","definition":"orange color or pigment; any of a range of colors between red and yellow"},{"id":"noun#2","pos":"noun","definition":"any citrus tree bearing oranges"},{"id":"noun#3","pos":"noun","definition":"any pigment producing the orange color"}],"cachedAt":1788515887676,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('pear', '{"word":"pear","phonetic":"/pєә/","translation":"n. 梨子, 梨树, 梨木","translations":[{"id":"translation#0","text":"梨子","pos":"n","source":"ecdict"},{"id":"translation#1","text":"梨树","pos":"n","source":"ecdict"},{"id":"translation#2","text":"梨木","pos":"n","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"sweet juicy gritty-textured fruit available in many varieties"},{"id":"noun#1","pos":"noun","definition":"Old World tree having sweet gritty-textured juicy fruit; widely cultivated in many varieties"}],"cachedAt":1788515887677,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('water', '{"word":"water","phonetic":"/''wɒ:tә/","translation":"n. 水, 雨水, 海水, 水位, 水面, 流水；vt. 给...浇水, 供以水, 注入水, 使湿","translations":[{"id":"translation#0","text":"水","pos":"n","source":"ecdict"},{"id":"translation#1","text":"雨水","pos":"n","source":"ecdict"},{"id":"translation#2","text":"海水","pos":"n","source":"ecdict"},{"id":"translation#3","text":"水位","pos":"n","source":"ecdict"},{"id":"translation#4","text":"水面","pos":"n","source":"ecdict"},{"id":"translation#5","text":"流水","pos":"n","source":"ecdict"},{"id":"translation#6","text":"给...浇水","pos":"vt","source":"ecdict"},{"id":"translation#7","text":"供以水","pos":"vt","source":"ecdict"},{"id":"translation#8","text":"注入水","pos":"vt","source":"ecdict"},{"id":"translation#9","text":"使湿","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"binary compound that occurs at room temperature as a clear colorless odorless tasteless liquid; freezes into ice below 0 degrees centigrade and boils above 100 degrees centigrade; widely used as a solvent"},{"id":"noun#1","pos":"noun","definition":"once thought to be one of four elements composing the universe (Empedocles)"},{"id":"noun#2","pos":"noun","definition":"a liquid necessary for the life of most animals and plants"},{"id":"verb#0","pos":"verb","definition":"supply with water, as with channels or ditches or streams"}],"cachedAt":1788517874759,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('milk', '{"word":"milk","phonetic":"/milk/","translation":"n. 奶, 乳状物；vt. 挤乳, 榨取","translations":[{"id":"translation#0","text":"奶","pos":"n","source":"ecdict"},{"id":"translation#1","text":"乳状物","pos":"n","source":"ecdict"},{"id":"translation#2","text":"挤乳","pos":"vt","source":"ecdict"},{"id":"translation#3","text":"榨取","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"a white nutritious liquid secreted by mammals and used as food by human beings"},{"id":"noun#1","pos":"noun","definition":"produced by mammary glands of female mammals for feeding their young"},{"id":"noun#2","pos":"noun","definition":"a river that rises in the Rockies in northwestern Montana and flows eastward to become a tributary of the Missouri River"},{"id":"noun#3","pos":"noun","definition":"any of several nutritive milklike liquids"}],"cachedAt":1788515887675,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
  ('egg', '{"word":"egg","phonetic":"/eg/","translation":"n. 蛋, 卵；vt. 挑唆, 煽动, 调蛋黄","translations":[{"id":"translation#0","text":"蛋","pos":"n","source":"ecdict"},{"id":"translation#1","text":"卵","pos":"n","source":"ecdict"},{"id":"translation#2","text":"挑唆","pos":"vt","source":"ecdict"},{"id":"translation#3","text":"煽动","pos":"vt","source":"ecdict"},{"id":"translation#4","text":"调蛋黄","pos":"vt","source":"ecdict"}],"senses":[{"id":"noun#0","pos":"noun","definition":"animal reproductive body consisting of an ovum or embryo together with nutritive and protective envelopes; especially the thin-shelled reproductive body laid by e.g. female birds"},{"id":"noun#1","pos":"noun","definition":"oval reproductive body of a fowl (especially a hen) used as food"},{"id":"verb#0","pos":"verb","definition":"throw eggs at"},{"id":"verb#1","pos":"verb","definition":"coat with beaten egg"}],"cachedAt":1788515887672,"status":"ok","phoneticStatus":"complete","translationStatus":"ok","spellingStatus":"valid","source":"ecdict"}'),
